fixtures/config/nginx.conf.text:
worker_processes 2;
events {
    worker_connections 8192;
}
http {
    root /www;
    default_type application/octet-stream;
    types {
        text/html html;
        text/plain txt;
    }
    client_max_body_size 64m;
    keepalive_timeout 2s;
    keepalive_requests 100;
    toksec_upstream_active 64;
    toksec_upstream_queue 8192;
    toksec_cache_bytes 4m;
    toksec_rate_per_second 0;

    upstream backend {
        server 127.0.0.1:8081;
        server 127.0.0.1:8082;
        keepalive 64;
    }
    include conf.d/servers.conf;
}
